// T and U are type parameters, each bound by the `any` constraint.
func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s))
	for i, v := range s {
		out[i] = f(v)
	}
	return out
}

func main() {
	// Inference deduces T=string, U=int from the arguments.
	fmt.Println(Map([]string{"go", "rocks"}, func(w string) int { return len(w) }))
	// Output: [2 5]
}

// A constraint is just an interface used in the [T ...] position.
func Join[T fmt.Stringer](xs []T) string {
	var b strings.Builder
	for i, x := range xs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(x.String()) // allowed: every T has String()
	}
	return b.String()
}

// net.IP satisfies fmt.Stringer, so T=net.IP is inferred.
// Join([]net.IP{ip1, ip2}) -> "10.0.0.1,10.0.0.2"

// The type set of Addable is exactly {int, string}.
type Addable interface {
	int | string
}

// + is the only arithmetic operator valid for BOTH int and string,
// so it is the sole such operation permitted on a value of type T.
func Concat[T Addable](a, b T) T {
	return a + b
}

func main() {
	fmt.Println(Concat(2, 3), Concat("go", "lang")) // Output: 5 golang
}

// ~int admits any type whose UNDERLYING type is int.
type Number interface {
	~int | ~float64
}

func Double[T Number](x T) T { return x + x }

type Celsius int // underlying type is int -> matches ~int

func main() {
	fmt.Println(Double(Celsius(21))) // Output: 42
	// Double with a plain `int` constraint would reject Celsius.
}

type Numeric interface {
	~int | ~int64 | ~float64
}

// + is valid for every member of the union, so this compiles.
func Sum[T Numeric](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

func main() {
	fmt.Println(Sum([]float64{1.5, 2.5, 3})) // Output: 7
	// total << 1 would NOT compile: << is invalid for float64.
}

// comparable enables ==; constraints.Ordered enables <, >.
func Index[T comparable](s []T, x T) int {
	for i, v := range s {
		if v == x { // == allowed by comparable
			return i
		}
	}
	return -1
}

func Max[T constraints.Ordered](a, b T) T {
	if a > b { // > allowed by Ordered
		return a
	}
	return b
}

func main() {
	// Type arguments inferred: Index[string], Max[int].
	fmt.Println(Index([]string{"a", "b"}, "b"), Max(3, 9)) // Output: 1 9
}

