// Keys returns the keys of m in unspecified order.
// K must be comparable (a Go requirement for map keys); V can be anything.
func Keys[K comparable, V any](m map[K]V) []K {
	out := make([]K, 0, len(m)) // pre-size: we know the count
	for k := range m {          // map iteration order is randomized
		out = append(out, k)
	}
	return out
}

