// Reduce folds s into a single value starting from init.
// T and U are `any`: we only move values and call f, never inspect them.
func Reduce[T, U any](s []T, init U, f func(acc U, elem T) U) U {
	acc := init
	for _, v := range s {
		acc = f(acc, v) // apply the folding function
	}
	return acc
}

// GroupBy buckets elements of s by the key derived from each element.
// K must be comparable because it is a map key; T is only stored, so `any`.
func GroupBy[T any, K comparable](s []T, key func(T) K) map[K][]T {
	out := make(map[K][]T)
	for _, v := range s {
		k := key(v)                 // derive the group key
		out[k] = append(out[k], v)  // nil slice appends fine on first insert
	}
	return out
}
